-- ============================================================
-- Sistem PPDB Online (Penerimaan Peserta Didik Baru) - PHP Native + MySQL
-- Import lewat phpMyAdmin atau:  mysql -u root -p < database/ppdb_online.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS ppdb_online CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ppdb_online;

DROP TABLE IF EXISTS berkas;
DROP TABLE IF EXISTS pendaftar;
DROP TABLE IF EXISTS jalur;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama_sekolah VARCHAR(120) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30),
  tahun_ajaran VARCHAR(20) NOT NULL,
  buka DATETIME NOT NULL,
  tutup DATETIME NOT NULL,
  pengumuman DATETIME NOT NULL,
  daftar_ulang_sampai DATE NOT NULL,
  persen_cadangan TINYINT NOT NULL DEFAULT 10
) ENGINE=InnoDB;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','verifikator') NOT NULL DEFAULT 'verifikator'
) ENGINE=InnoDB;

CREATE TABLE jalur (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  nama VARCHAR(60) NOT NULL,
  kuota SMALLINT NOT NULL,
  keterangan VARCHAR(255)
) ENGINE=InnoDB;

CREATE TABLE pendaftar (
  id INT AUTO_INCREMENT PRIMARY KEY,
  no_daftar VARCHAR(20) NOT NULL UNIQUE,
  jalur_id INT NOT NULL,
  nisn CHAR(10) NOT NULL UNIQUE,
  nik CHAR(16),
  nama VARCHAR(100) NOT NULL,
  jk ENUM('L','P') NOT NULL DEFAULT 'L',
  tempat_lahir VARCHAR(60),
  tgl_lahir DATE NOT NULL,
  agama VARCHAR(20),
  asal_sekolah VARCHAR(100),
  alamat VARCHAR(255),
  jarak_km DECIMAL(5,2) NOT NULL DEFAULT 0,
  nama_ayah VARCHAR(100),
  nama_ibu VARCHAR(100),
  pekerjaan_ortu VARCHAR(60),
  telepon VARCHAR(20) NOT NULL,
  nilai_rata DECIMAL(5,2) NOT NULL DEFAULT 0,
  poin_prestasi DECIMAL(5,2) NOT NULL DEFAULT 0,
  prestasi_ket VARCHAR(255),
  status ENUM('draft','menunggu','perbaikan','terverifikasi','diterima','cadangan','tidak_diterima','daftar_ulang') NOT NULL DEFAULT 'draft',
  catatan VARCHAR(255),
  skor DECIMAL(6,2) NULL,
  peringkat SMALLINT NULL,
  verifikator_id INT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  dikirim_at DATETIME NULL,
  diverifikasi_at DATETIME NULL,
  INDEX (status), INDEX (jalur_id),
  FOREIGN KEY (jalur_id) REFERENCES jalur(id),
  FOREIGN KEY (verifikator_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE berkas (
  id INT AUTO_INCREMENT PRIMARY KEY,
  pendaftar_id INT NOT NULL,
  jenis VARCHAR(20) NOT NULL,
  file VARCHAR(100) NOT NULL,
  uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_jenis (pendaftar_id, jenis),
  FOREIGN KEY (pendaftar_id) REFERENCES pendaftar(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Jadwal contoh: pendaftaran sedang dibuka (dibuka 10 hari lalu, ditutup 3 hari lagi)
  TIMESTAMP(CURDATE() - INTERVAL 10 DAY, '08:00:00'), TIMESTAMP(CURDATE() + INTERVAL 3 DAY, '23:59:00'),
  TIMESTAMP(CURDATE() + INTERVAL 7 DAY, '10:00:00'), CURDATE() + INTERVAL 12 DAY, 10);

